(() => {
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const money=(c,cur)=>new Intl.NumberFormat(undefined,{style:'currency',currency:cur||'USD'}).format((Number(c)||0)/100);
  const csrf=()=>document.querySelector('meta[name="csrf-token"]')?.content||'';
  async function request(url,options={}){const r=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json',...(options.headers||{})},...options});const p=await r.json();if(!r.ok||!p.ok)throw new Error(p.message||'Request failed.');return p.data;}
  function card(item){return `<article class="mg-review-card" data-id="${esc(item.public_id)}"><div><span>${esc(item.review_status)} · ${esc(item.readiness_status)}</span><h2>${esc(item.bundle_title)}</h2><p>${esc(item.merchant_name)} · Order ${esc(item.order_public_id)}</p></div><dl><div><dt>Gross</dt><dd>${money(item.gross_amount_cents,item.currency)}</dd></div><div><dt>Fee</dt><dd>${money(item.commission_amount_cents,item.currency)}</dd></div><div><dt>Payable</dt><dd>${money(item.payable_amount_cents,item.currency)}</dd></div></dl><label>Reason<input type="text" maxlength="255" data-reason value="${esc(item.review_reason||'')}"></label><div class="mg-review-actions"><button data-action="approve">Approve</button><button data-action="hold">Hold</button><button data-action="block">Block</button><button data-action="mark_release_ready">Release ready</button><button data-action="reopen">Reopen</button></div></article>`;}
  async function load(root){const list=root.querySelector('[data-review-list]');list.setAttribute('aria-busy','true');try{const data=await request('/api/admin/bundle-settlement-reviews.php?action=queue');list.innerHTML=data.items.length?data.items.map(card).join(''):'<div class="mg-review-empty">No settlements require review.</div>';root.querySelector('[data-review-summary]').textContent=`${data.items.length} settlement${data.items.length===1?'':'s'} · transfers disabled`;}catch(e){list.innerHTML=`<div class="mg-review-empty">${esc(e.message)}</div>`;}list.setAttribute('aria-busy','false');}
  async function review(root,button){const card=button.closest('[data-id]');button.disabled=true;try{await request('/api/admin/bundle-settlement-reviews.php',{method:'POST',body:JSON.stringify({action:'review',settlement_id:card.dataset.id,review_action:button.dataset.action,reason:card.querySelector('[data-reason]').value,csrf_token:csrf(),idempotency_key:`bundle-review-${card.dataset.id}-${button.dataset.action}-${Date.now()}`})});await load(root);}catch(e){alert(e.message);button.disabled=false;}}
  document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('[data-settlement-review-page]');if(!root)return;root.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)review(root,b);if(e.target.closest('[data-refresh]'))load(root);});load(root);});
})();